CREATE TABLE "Epoch" ("id" BIGINT PRIMARY KEY,"chainId" INTEGER NOT NULL,"startTime" TIMESTAMP(3) NOT NULL,"endTime" TIMESTAMP(3) NOT NULL,"totalSignals" INTEGER NOT NULL DEFAULT 0,"uniqueParticipants" INTEGER NOT NULL DEFAULT 0,"totalExtensionSeconds" INTEGER NOT NULL DEFAULT 0,"status" TEXT NOT NULL,"startBlock" BIGINT NOT NULL,"finalizeBlock" BIGINT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "Epoch_chainId_id_key" ON "Epoch"("chainId","id");
CREATE TABLE "Signal" ("id" TEXT PRIMARY KEY,"chainId" INTEGER NOT NULL,"epochId" BIGINT NOT NULL,"wallet" TEXT NOT NULL,"timestamp" TIMESTAMP(3) NOT NULL,"extensionSeconds" INTEGER NOT NULL,"blockNumber" BIGINT NOT NULL,"blockHash" TEXT NOT NULL,"transactionHash" TEXT NOT NULL,"logIndex" INTEGER NOT NULL,"points" INTEGER NOT NULL DEFAULT 10,CONSTRAINT "Signal_epochId_fkey" FOREIGN KEY("epochId") REFERENCES "Epoch"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "Signal_chainId_transactionHash_logIndex_key" ON "Signal"("chainId","transactionHash","logIndex"); CREATE INDEX "Signal_chainId_epochId_wallet_idx" ON "Signal"("chainId","epochId","wallet"); CREATE INDEX "Signal_chainId_blockNumber_idx" ON "Signal"("chainId","blockNumber");
CREATE TABLE "Participant" ("id" TEXT PRIMARY KEY,"chainId" INTEGER NOT NULL,"epochId" BIGINT NOT NULL,"wallet" TEXT NOT NULL,"signalCount" INTEGER NOT NULL DEFAULT 0,"points" INTEGER NOT NULL DEFAULT 0,"firstSignalAt" TIMESTAMP(3) NOT NULL,"lastSignalAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Participant_epochId_fkey" FOREIGN KEY("epochId") REFERENCES "Epoch"("id") ON DELETE RESTRICT ON UPDATE CASCADE); CREATE UNIQUE INDEX "Participant_chainId_epochId_wallet_key" ON "Participant"("chainId","epochId","wallet"); CREATE INDEX "Participant_chainId_wallet_idx" ON "Participant"("chainId","wallet");
CREATE TABLE "IndexerCursor" ("chainId" INTEGER PRIMARY KEY,"nextBlock" BIGINT NOT NULL,"lastBlockHash" TEXT,"chainHead" BIGINT,"error" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "BlockCheckpoint" ("chainId" INTEGER NOT NULL,"blockNumber" BIGINT NOT NULL,"blockHash" TEXT NOT NULL,"parentHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY("chainId","blockNumber"));
CREATE TABLE "Reward" ("id" TEXT PRIMARY KEY,"chainId" INTEGER NOT NULL,"wallet" TEXT NOT NULL,"epochId" BIGINT,"kind" TEXT NOT NULL,"points" INTEGER NOT NULL DEFAULT 0,"sourceTransactionHash" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE UNIQUE INDEX "Reward_chainId_wallet_epochId_kind_key" ON "Reward"("chainId","wallet","epochId","kind");
CREATE TABLE "Achievement" ("id" TEXT PRIMARY KEY,"chainId" INTEGER NOT NULL,"wallet" TEXT NOT NULL,"epochId" BIGINT,"kind" TEXT NOT NULL,"unlockedAt" TIMESTAMP(3) NOT NULL,"sourceTransactionHash" TEXT); CREATE UNIQUE INDEX "Achievement_chainId_wallet_epochId_kind_key" ON "Achievement"("chainId","wallet","epochId","kind");
CREATE TABLE "HealthProbe" ("marker" TEXT PRIMARY KEY,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
